'use strict';

// MODULES //

var BigInt = require( '@stdlib/bigint/ctor' );
var ToPrimitiveSymbol = require( '@stdlib/symbol/to-primitive' );
var Uint32Array = require( '@stdlib/array/uint32' );
var format = require( '@stdlib/string/format' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var hasToPrimitiveSymbolSupport = require( '@stdlib/assert/has-to-primitive-symbol-support' ); // eslint-disable-line id-length
var isArray = require( '@stdlib/assert/is-array' );
var isBigInt = require( '@stdlib/assert/is-bigint' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isString = require( '@stdlib/assert/is-string' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var setEnumerableReadOnly = require( '@stdlib/utils/define-read-only-property' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var asBigUint64 = require( './asbiguint64.js' );
var toStr = require( './tostring.js' );
var toJSON = require( './tojson.js' );
var valueOf = require( './valueof.js' ); // eslint-disable-line stdlib/no-redeclare


// MAIN //

/**
* Unsigned 64-bit integer constructor.
*
* @constructor
* @param {number|string|number[]|Uint32Array|BigInt} value - numeric value or high low words or BigInt // TODO: Which ones should we keep and discard?
* @throws {TypeError} must invoke using the `new` keyword
* @throws {TypeError} value must be a number or bla bla bla // TODO: update after review
* @returns {Uint64} Unsigned 64-bit integer
*
* @example // TODO: add more example
* var x = new Uint64( 5 );
* // returns <Uint64>
*/
function Uint64( value ) {
	var hasBigInt = hasBigIntSupport();
	if ( !( this instanceof Uint64 ) ) {
		throw new TypeError( 'invalid invocation. Constructor must be called with the `new` keyword.' );
	}

	// TODO: current implementation uses either BigInt or Uint32Array for the internal representation
	// Are there other better alternative instead of Uint32Array? How is plain old number array?
	// Or an object with high and low props?

	if ( isBigInt( value ) ) {
		setEnumerableReadOnly( this, 'value', asBigUint64( value ) );
	}
	else if ( isUint32Array( value ) ) {
		if ( value.length === 2 ) {
			if ( hasBigInt ) {
				setEnumerableReadOnly( this, 'value', ( BigInt( value[ 0 ] ) << BigInt( 32 ) ) | BigInt( value[ 1 ] ) );
			}
			else {
				setEnumerableReadOnly( this, 'value', value );
			}
		}
		else {
			throw new TypeError( format( 'invalid argument. Provided Uint32Array must have a length of 2. Value: `%s`.', value ) );
		}
	}
	else if ( isArray( value ) ) {
		if ( value.length === 2 ) {
			if ( typeof value[ 0 ] === 'number' && typeof value[ 1 ] === 'number' ) {
				value[ 0 ] >>>= 0;
				value[ 1 ] >>>= 0;
				if ( hasBigInt ) {
					setEnumerableReadOnly( this, 'value', ( BigInt( value[ 0 ] ) << BigInt( 32 ) ) | BigInt( value[ 1 ] ) );
				}
				else {
					setEnumerableReadOnly( this, 'value', new Uint32Array( value ) );
				}
			}
			else {
				throw new TypeError( format( 'invalid argument. Provided array must contain only elements of type number. Value: `%s`.', value ) );
			}
		}
		else {
			throw new TypeError( format( 'invalid argument. Provided array must have a length of 2. Value: `%s`.', value ) );
		}
	}
	else if ( isString( value ) ) {
		if ( hasBigInt ) {
			try {
				setEnumerableReadOnly( this, 'value', asBigUint64( BigInt( value ) ) );
			}
			// eslint-disable-next-line no-unused-vars
			catch ( error ) {
				throw new TypeError( format( 'invalid argument. Could not convert string to BigInt. Value: `%s`.', value ) );
			}
		}
		else {
			// TODO: decompose into high low
			setEnumerableReadOnly( this, 'value', new Uint32Array( [ 0, 0 ] ) );
		}
	}
	else if ( isNumber( value ) ) {
		value >>>= 0;
		if ( hasBigInt ) {
			setEnumerableReadOnly( this, 'value', asBigUint64( BigInt( value ) ) );
		}
		else {
			setEnumerableReadOnly( this, 'value', new Uint32Array( [ 0, value ] ) );
		}
	}
	else {
		throw new TypeError( format( 'invalid argument. Must provide a number or string or number[] or Uint32Array or BigInt. Value: `%s`.', value ) );
	}
	return this;
}

/**
* Constructor name.
*
* @name name
* @memberof Uint64
* @readonly
* @type {string}
* @default 'Uint64'
*
* @example
* var name = Uint64.name;
* // returns 'Uint64'
*/
setReadOnly( Uint64, 'name', 'Uint64' );

/**
* Size (in bytes) of the underlying value.
*
* @name BYTES_PER_ELEMENT
* @memberof Uint64
* @type {integer}
* @returns {integer} size in bytes
*
* @example
* var nbytes = Uint64.BYTES_PER_ELEMENT;
* // returns 8
*/
setReadOnly( Uint64, 'BYTES_PER_ELEMENT', 8 );

/**
* Size (in bytes) of the underlying value.
*
* @name BYTES_PER_ELEMENT
* @memberof Uint64.prototype
* @type {integer}
* @returns {integer} size in bytes
*
* @example
* var x = new Uint64( 5 );
*
* var nbytes = x.BYTES_PER_ELEMENT;
* // returns 8
*/
setReadOnly( Uint64.prototype, 'BYTES_PER_ELEMENT', 8 );

/**
* Serializes an unsigned 64-bit integer number as a string.
*
* @name toString
* @memberof Uint64.prototype
* @type {Function}
* @returns {string} serialized unsigned 64-bit integer number
*
* @example
* var x = new Uint64( 5 );
*
* var str = x.toString();
* // returns '5'
*/
setReadOnly( Uint64.prototype, 'toString', toStr );

/**
* Serializes an unsigned 64-bit integer number as a JSON object.
*
* ## Notes
*
* -   `JSON.stringify()` implicitly calls this method when stringifying a `Uint64` instance.
*
* @name toJSON
* @memberof Uint64.prototype
* @type {Function}
* @returns {Object} serialized unsigned 64-bit integer number
*
* @example
* var x = new Uint64( 5 );
*
* var obj = x.toJSON();
* // returns { 'type': 'Uint64', 'value': '5' }
*/
setReadOnly( Uint64.prototype, 'toJSON', toJSON );

/**
* Converts an unsigned 64-bit integer number to a primitive value.
*
* @name valueOf
* @memberof Uint64.prototype
* @type {Function}
* @returns {number} primitive value
*
* @example
* var x = new Uint64( 5 );
*
* var v = x.valueOf();
* // returns 5.0
*/
setReadOnly( Uint64.prototype, 'valueOf', valueOf );

/**
* Returns the primitive value of an unsigned 64-bit integer number.
*
* @name toPrimitive
* @memberof Uint64.prototype
* @type {Function}
* @param {string} hint - conversion hint
* @returns {number} primitive value
*
* @example
* var hasSymbol = require( '@stdlib/assert/has-to-primitive-symbol-support' );
* var ToPrimitiveSymbol = require( '@stdlib/symbol/to-primitive' );
*
* var x = new Uint64( 5 );
*
* var v;
* if ( hasSymbol() ) {
*     v = x[ ToPrimitiveSymbol ]( 'number' );
*     // returns 5.0
* }
*/
if ( hasToPrimitiveSymbolSupport() ) {
	setReadOnly( Uint64.prototype, ToPrimitiveSymbol, valueOf );
}


// EXPORTS //

module.exports = Uint64;
